def max_original_length(p: str) -> int:
    p = int(p)
    length = 0
    current_p = p

    while current_p > 0:
        # Find the largest two numbers x and y such that x >= y
        # and concat(x, y) <= current_p.
        for x in range(9, 0, -1):
            if x > current_p:
                continue
            y_str = ""
            for y in range(9, -1, -1):
                if int(str(x) + str(y)) <= current_p:
                    y_str = str(y)
                    break
            if y_str:
                # Concatenate x and y
                x = int(str(x) + y_str)
                current_p -= x
                length += 2
                break
        else:
            # If no such pair is found, we must have a single number.
            length += 1
            break

    return length

