    n = len(p_str)

    def can_form(x, y):
        # Try to form the number x followed by y or y followed by x
        return x + y == p_str or y + x == p_str

    max_length = 1
    for i in range(1, n):
        if can_form(p_str[:i], p_str[i:]):
            max_length = 2
            break

    if max_length == 1:
        return 1

